// Pages whose main content is a wide reference table: the supported content
// types (`content-types/*`, generated by `scripts/sync_kb.py`, including frozen
// release snapshots) and the model label tables (`models/*`). These pages drop
// the "On this page" pane and use the compact table styles in global.css.
const WIDE_TABLE_ROUTE_PREFIXES = ["content-types/", "models/"];

/** Returns whether the Starlight route `id` is a wide reference table page. */
export function isWideTablePage(id: string): boolean {
  return (
    id === "content-types" ||
    WIDE_TABLE_ROUTE_PREFIXES.some((prefix) => id.startsWith(prefix))
  );
}
